#!/usr/bin/env python3
"""Reconcile a batch of payment transactions from a CSV file."""
import json
import re
import sys
from datetime import datetime
from decimal import Decimal

# Amount must be a non‑negative decimal number with at most two fractional digits.
AMOUNT_RE = re.compile(r"\d+(\.\d{1,2})?")
STATUSES = {"SUCCESS", "FAILED", "PENDING"}


def parse_timestamp(value):
    """Return the timestamp as an aware datetime, or ``None`` if invalid.

    The input format must be ISO‑8601 with an explicit offset. The specification
    for this script allows a trailing ``Z`` to indicate UTC. ``datetime.fromisoformat``
    does not understand ``Z``, so we translate it to ``+00:00`` before parsing.
    """
    # Convert a trailing 'Z' (UTC) to '+00:00' which ``fromisoformat`` accepts.
    if value.endswith("Z"):
        value = value[:-1] + "+00:00"
    try:
        ts = datetime.fromisoformat(value)
    except ValueError:
        return None
    # Ensure the datetime is timezone‑aware.
    if ts.tzinfo is None:
        return None
    return ts


def parse_row(line):
    fields = line.split(",")
    if len(fields) != 4 or any(f == "" for f in fields):
        return None
    tx_id, timestamp, amount, status = fields
    ts = parse_timestamp(timestamp)
    if ts is None or not AMOUNT_RE.fullmatch(amount) or status not in STATUSES:
        return None
    # Use Decimal for exact monetary arithmetic.
    return tx_id, ts, Decimal(amount), status


def reconcile(path):
    latest = {}
    with open(path, encoding="utf-8") as f:
        # Skip header line.
        next(f, None)
        for line in f:
            row = parse_row(line.rstrip("\n"))
            if row is None:
                print(f"skipping malformed row: {line!r}", file=sys.stderr)
                continue
            tx_id, ts, amount, status = row
            current = latest.get(tx_id)
            if current is None or ts > current[1]:
                latest[tx_id] = row

    total = Decimal(0)
    valid = failed = 0
    for _, _, amount, status in latest.values():
        if status == "SUCCESS":
            total += amount
            valid += 1
        elif status == "FAILED":
            failed += 1
    # Round to two decimal places exactly.
    total_rounded = total.quantize(Decimal('0.01'))
    return {
        "total_valid_amount": float(total_rounded),
        "valid_count": valid,
        "failed_count": failed,
    }


def main():
    # Expect exactly one argument: the CSV file path.
    if len(sys.argv) != 2:
        print("usage: reconcile.py <input.csv>", file=sys.stderr)
        sys.exit(2)
    print(json.dumps(reconcile(sys.argv[1])))


if __name__ == "__main__":
    main()
